"use client"

import { useMemo, useRef } from "react"
import type { Market } from "@mrdoge/protocol"
import type { OddsMovement } from "@/registry/mrdoge-ui/odds-selector/odds-selector"

/**
 * Diffs each bet item's price against the price it had the last time this
 * hook saw a market for the same match, so an Odds Selector can show
 * up/down indicators as live odds change. Movement isn't something the SDK
 * computes or sends — `odds.subscribe` pushes a full replace-in-place
 * snapshot on every change (see useLiveOdds), so this hook remembers the
 * previous snapshot's prices itself and compares.
 *
 * A bet item with no prior snapshot to compare against (first time seen,
 * or the match/market just changed) has no entry in the result — nothing
 * to compare yet, not a "flat" tick. An unchanged price also has no entry,
 * on purpose: an indicator that never goes away would just be noise.
 */
export function useOddsMovement(
  market: Market | null | undefined
): Record<string, OddsMovement> {
  const previousPrices = useRef<Map<string, number>>(new Map())

  return useMemo(() => {
    if (!market) return {}

    const movement: Record<string, OddsMovement> = {}
    const nextPrices = new Map<string, number>()

    for (const item of market.betItems) {
      const previous = previousPrices.current.get(item.id)
      if (previous !== undefined && item.price !== previous) {
        movement[item.id] = item.price > previous ? "up" : "down"
      }
      nextPrices.set(item.id, item.price)
    }

    previousPrices.current = nextPrices
    return movement
  }, [market])
}

"use client"

import { cn } from "@/lib/utils"

export type OddsMovement = "up" | "down" | "flat"

export interface OddsOption {
  id: string
  /** Selection label, e.g. "1", "X", "2" or a team name / "Draw". */
  label: string
  /** Formatted price, e.g. "1.85". */
  price: string
  movement?: OddsMovement
  suspended?: boolean
}

export interface OddsSelectorProps {
  /** Market name shown as a header above the options, e.g. "Match Result". Omit to render just the options. */
  label?: string
  options: OddsOption[]
  selectedId?: string
  /** Called with the pressed option's id, or `undefined` when pressing the already-selected option deselects it. */
  onSelect?: (id: string | undefined) => void
  /**
   * "card" (default) renders its own border/background, for standalone
   * use. "bare" drops that chrome — for embedding inside another card
   * (e.g. Match Card's odds row) without a card-in-a-card look.
   */
  variant?: "card" | "bare"
  className?: string
}

// A price shortening (going down) means the market now thinks the outcome
// is more likely — the conventional "hot" direction in real odds boards,
// shown green. Drifting (going up) means the opposite, shown red. Same
// mechanical rule regardless of market type.
const movementColor: Record<OddsMovement, string> = {
  up: "text-destructive",
  down: "text-emerald-600 dark:text-emerald-500",
  flat: "",
}

export function OddsSelector({
  label,
  options,
  selectedId,
  onSelect,
  variant = "card",
  className,
}: OddsSelectorProps) {
  return (
    <div
      className={cn(
        "flex h-full flex-col overflow-hidden",
        variant === "card" && "rounded-xl border bg-card",
        className
      )}
    >
      {label ? (
        <div className="border-b px-3 py-2 text-sm font-medium text-card-foreground">
          {label}
        </div>
      ) : null}
      <div className="grid flex-1 auto-cols-fr grid-flow-col divide-x">
        {options.map((option) => {
          const selected = option.id === selectedId

          return (
            <button
              key={option.id}
              type="button"
              disabled={option.suspended}
              onClick={() => onSelect?.(selected ? undefined : option.id)}
              className={cn(
                "flex min-w-0 flex-col items-center justify-center gap-0.5 px-2 py-2.5 transition-colors",
                selected ? "bg-primary text-primary-foreground" : "hover:bg-accent/50",
                option.suspended && "pointer-events-none opacity-50"
              )}
            >
              <span
                className={cn(
                  "max-w-full truncate text-xs",
                  selected ? "text-primary-foreground/70" : "text-muted-foreground"
                )}
              >
                {option.label}
              </span>
              <span
                className={cn(
                  "text-sm font-semibold",
                  !selected && !option.suspended && option.movement && movementColor[option.movement]
                )}
              >
                {option.suspended ? "—" : option.price}
              </span>
            </button>
          )
        })}
      </div>
    </div>
  )
}
